-- Correct the product-owned seeded guide; organization articles and access are unchanged.
update public.library_articles
set title = 'Submit an IT request',
    summary = 'Describe an IT issue, attach supporting files, and follow your request.',
    content = '[{"type": "heading", "text": "1. Open the request form"}, {"type": "paragraph", "text": "Choose Submit a request on Home or New request in My requests. For an assigned device, open it in My equipment and use its support action to include the equipment reference."}, {"type": "heading", "text": "2. Describe the issue"}, {"type": "paragraph", "text": "Enter a clear subject and description, then choose the impact that best matches who is affected. Include any error message and the checks you already tried. Category and location are optional; expand the extra details if they help explain the issue. IT handles assignment and routing."}, {"type": "heading", "text": "3. Add supporting files"}, {"type": "paragraph", "text": "You can attach files before submitting the request. Add up to 5 files, no larger than 10 MB each. Use the file picker for the supported file types. Include a screenshot or document if it helps IT understand the problem. Do not include passwords or other sensitive credentials."}, {"type": "heading", "text": "4. Submit and follow progress"}, {"type": "paragraph", "text": "Read any suggested help articles if useful, then choose Submit request. Wait for the saved request and reference number. Open My requests to follow progress, read replies from IT, and add an update."}, {"type": "heading", "text": "If something goes wrong"}, {"type": "paragraph", "text": "If a field needs attention or saving fails, keep the form open and follow the error guidance. If you are unsure whether submission succeeded, check My requests before submitting the same issue again. For equipment orders rather than faults, use Request equipment on the Equipment requests tab; inventory access is required."}]'::jsonb
where id = '16610b18-b509-5736-9334-6ce53ac38369'
  and title = 'FixxFlow: create a ticket for yourself or another requester';
